/* @autogenerated */
package net.civeira.phylax.feature.oauth.session.infrastructure.driven;

import java.util.List;
import java.util.Set;
import java.util.UUID;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;

import net.civeira.phylax.feature.oauth.authentication.domain.AuthenticationData;
import net.civeira.phylax.feature.oauth.client.domain.ClientDetails;
import net.civeira.phylax.feature.oauth.session.domain.SessionInfo;
import net.civeira.phylax.testing.sql.H2Database;

/** The browser sessions and their tokens stored with the production sql on h2. */
class SessionStoreSqlAdapterUnitTest {
  private H2Database db;
  private SessionStoreSqlAdapter sessions;

  @BeforeEach
  void setUp() {
    db = new H2Database();
    sessions =
        new SessionStoreSqlAdapter(db.dataSource(), new ObjectMapper().findAndRegisterModules()
            .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false));
  }

  private String session(String clientId) {
    String state = UUID.randomUUID().toString();
    AuthenticationData auth = new AuthenticationData();
    auth.setUid("user-uid");
    auth.setUsername("alice");
    auth.setTenant("tenant-uid");
    auth.setScopes(List.of("openid", "profile"));
    sessions.saveSession(state, ClientDetails.builder().clientId(clientId).allowedScopes(List.of())
        .allowedGrants(List.of()).build(), "form", auth, "csid-1");
    return state;
  }

  @Test
  @DisplayName("A saved session is loaded with its client, user and a public session id")
  void save_and_load() {
    String state = session("web");

    SessionInfo info = sessions.loadSession(state).orElseThrow();
    Assertions.assertEquals("web", info.getClientId());
    Assertions.assertEquals("form", info.getGrant());
    Assertions.assertEquals("csid-1", info.getCsid());
    Assertions.assertEquals("user-uid", info.getUserId());
    Assertions.assertEquals("alice", info.getValidationData().getUsername());
    Assertions.assertNotNull(info.getValidationData().getSid(), "A public session id is assigned");
    Assertions.assertTrue(sessions.loadSession("missing").isEmpty());
  }

  @Test
  @DisplayName("The tokens issued on a session register its participating clients")
  void tokens_and_participants() {
    String state = session("web");
    String refresh = UUID.randomUUID().toString();

    sessions.updateTokenJtis(state, UUID.randomUUID().toString(), refresh);
    sessions.updateTokenJtis(state, "mobile", UUID.randomUUID().toString(),
        UUID.randomUUID().toString());

    Assertions.assertEquals(Set.of("web", "mobile"), sessions.participatingClients(state));
    Assertions.assertTrue(sessions.participatingClients(null).isEmpty());
    Assertions.assertTrue(sessions.isRefreshSessionActive(refresh));
    Assertions.assertFalse(sessions.isRefreshSessionActive(UUID.randomUUID().toString()));
    Assertions.assertEquals(2, db.count("_oauth_session_token", null));
  }

  @Test
  @DisplayName("A refresh rotation replaces the tokens of the session")
  void rotate_by_refresh() {
    String state = session("web");
    String refresh = UUID.randomUUID().toString();
    sessions.updateTokenJtis(state, UUID.randomUUID().toString(), refresh);
    String next = UUID.randomUUID().toString();

    Assertions.assertTrue(
        sessions.updateTokenJtisByRefreshJti(refresh, UUID.randomUUID().toString(), next));
    Assertions.assertTrue(sessions.isRefreshSessionActive(next));
    Assertions.assertFalse(
        sessions.updateTokenJtisByRefreshJti(UUID.randomUUID().toString(),
            UUID.randomUUID().toString(), UUID.randomUUID().toString()),
        "An unknown refresh does not rotate");
  }

  @Test
  @DisplayName("A session can change its identifier and be deleted with its tokens")
  void update_and_delete() {
    String state = session("web");
    String refresh = UUID.randomUUID().toString();
    sessions.updateTokenJtis(state, UUID.randomUUID().toString(), refresh);
    String renewed = UUID.randomUUID().toString();

    sessions.updateSession(renewed, state);
    Assertions.assertTrue(sessions.loadSession(state).isEmpty());
    Assertions.assertTrue(sessions.loadSession(renewed).isPresent());

    sessions.deleteSession(renewed);
    Assertions.assertTrue(sessions.loadSession(renewed).isEmpty());
    Assertions.assertFalse(sessions.isRefreshSessionActive(refresh),
        "The tokens die with the session");
  }
}
